CREATE TABLE meta(key TEXT PRIMARY KEY,value TEXT NOT NULL) STRICT;
CREATE TABLE clients(id TEXT PRIMARY KEY,name TEXT NOT NULL,contact_name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT NOT NULL,address TEXT NOT NULL,notes TEXT NOT NULL,archived INTEGER NOT NULL CHECK(archived IN(0,1)),version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL) STRICT;
CREATE TABLE templates(id TEXT PRIMARY KEY,name TEXT NOT NULL,normalized_name TEXT NOT NULL,notes TEXT NOT NULL,position INTEGER NOT NULL UNIQUE,archived INTEGER NOT NULL CHECK(archived IN(0,1)),version INTEGER NOT NULL CHECK(version>0)) STRICT;
CREATE UNIQUE INDEX template_name ON templates(normalized_name) WHERE archived=0;
CREATE TABLE orders(id TEXT PRIMARY KEY,number TEXT NOT NULL UNIQUE,client_id TEXT NOT NULL REFERENCES clients(id),name TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('draft','confirmed')),document TEXT NOT NULL CHECK(json_valid(document)),total_fils INTEGER CHECK(total_fils BETWEEN 0 AND 9000000000000),known_total_fils INTEGER NOT NULL CHECK(known_total_fils BETWEEN 0 AND 9000000000000),archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)),version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL) STRICT;
CREATE INDEX order_client ON orders(client_id,created_at);
CREATE TABLE revisions(order_id TEXT NOT NULL REFERENCES orders(id),version INTEGER NOT NULL,document TEXT NOT NULL CHECK(json_valid(document)),total_fils INTEGER,known_total_fils INTEGER NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,device_id TEXT NOT NULL,PRIMARY KEY(order_id,version)) STRICT;
CREATE TABLE payments(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),kind TEXT NOT NULL CHECK(kind IN('receipt','correction')),original_id TEXT UNIQUE REFERENCES payments(id),amount_fils INTEGER NOT NULL CHECK(amount_fils BETWEEN 1 AND 9000000000000),business_date TEXT NOT NULL,method TEXT NOT NULL CHECK(method IN('cash','bank','card','other')),reference TEXT NOT NULL,notes TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,device_id TEXT NOT NULL,CHECK((kind='receipt' AND original_id IS NULL) OR (kind='correction' AND original_id IS NOT NULL AND length(trim(reason))>0))) STRICT;
CREATE INDEX payment_order ON payments(order_id,business_date,created_at);
CREATE TABLE requests(id TEXT PRIMARY KEY,hash TEXT NOT NULL,result TEXT NOT NULL CHECK(json_valid(result))) STRICT;
CREATE TABLE audit(id TEXT PRIMARY KEY,entity_id TEXT NOT NULL,action TEXT NOT NULL,before_json TEXT,after_json TEXT,reason TEXT NOT NULL,device_id TEXT NOT NULL,created_at TEXT NOT NULL) STRICT;
